A reactivation path added by a teammate:

async enroll(userId: string, courseId: string) {
  const course = await this.requireCourse(courseId);
  const current = await this.enrollments.findByUserAndCourse(userId, courseId);
  if (current?.status === "active") return { outcome: "existing", enrollment: current };
  if (current?.status === "cancelled") {
    // they were allowed in once
    const reactivated = { ...current, status: "active" as const };
    await this.enrollments.save(reactivated);
    return { outcome: "reactivated", enrollment: reactivated };
  }
  this.assertPublished(course);
  await this.assertPrerequisites(userId, course);
  await this.assertEntitlement(userId, course);
  // ... create
}

